import org.gameflex.tv.LocalRom;
public class LocalRomTest{public static void main(String[] args)throws Exception{byte[] b=new byte[16+16384+8192];b[0]='N';b[1]='E';b[2]='S';b[3]=26;b[4]=1;b[5]=1;if(!LocalRom.system(b).equals("nes"))throw new AssertionError();if(!LocalRom.id(b).equals(LocalRom.id(b.clone())))throw new AssertionError();if(LocalRom.validId("../save")||LocalRom.validId("not-a-hash"))throw new AssertionError();for(byte[] bad:new byte[][]{new byte[0],new byte[8],new byte[LocalRom.MAX_BYTES+1]}){try{LocalRom.system(bad);throw new AssertionError();}catch(IllegalArgumentException expected){}}byte[] gb=new byte[32768];gb[0x147]=0;int sum=0;for(int i=0x134;i<=0x14c;i++)sum=(sum-(gb[i]&255)-1)&255;gb[0x14d]=(byte)sum;if(!LocalRom.system(gb).equals("gb"))throw new AssertionError();gb[0x143]=(byte)192;sum=0;for(int i=0x134;i<=0x14c;i++)sum=(sum-(gb[i]&255)-1)&255;gb[0x14d]=(byte)sum;if(!LocalRom.system(gb).equals("gbc"))throw new AssertionError();System.out.println("Local ROM formats, content identity, limits and save-path bounds passed.");}}
